// ============================================================
// Helper Functions
// ============================================================
function getPolygonContract(name) {
    return exports.POLYGON_CONTRACTS[name];
}
function getRamesttaContract(name) {
    return exports.RAMESTTA_CONTRACTS[name];
}
function getNetwork(chainId) {
    return Object.values(exports.NETWORKS).find((n) => n.chainId === chainId);
}
function isRamesttaChainId(chainId) {
    return chainId === 1370 || chainId === 1371;
}
function isPolygonChainId(chainId) {
    return chainId === 137;
}
